package vn.codegym.mvc.controller;import vn.codegym.mvc.model.Product;import vn.codegym.mvc.service.*;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.HttpServletRequest;import java.math.BigDecimal;
@WebServlet("/products") public final class ProductServlet extends CrudServlet<Product>{private final ProductServiceImpl service=new ProductServiceImpl();protected MemoryService<Product> service(){return service;}protected String kind(){return "products";}protected String title(){return "Quản lý sản phẩm";}protected Product input(HttpServletRequest r){String name=field(r,"name",100),description=field(r,"description",2000),manufacturer=field(r,"manufacturer",100);BigDecimal price=new BigDecimal(field(r,"price",30));if(price.signum()<0||price.scale()>2||price.compareTo(new BigDecimal("999999999.99"))>0)throw new IllegalArgumentException("Giá không hợp lệ.");return new Product(name,price,description,manufacturer);}}
